from __future__ import absolute_import
from selenium.webdriver.common.by import By
from taf.selenium.sbts.common.exceptions import UnexpectedElementState
from taf.selenium.sbts.pages import bts_status
from taf.selenium.sbts.pages import v24r3


class BtsStatus(v24r3.BtsStatus):

    def __init__(self, driver):
        super(BtsStatus, self).__init__(driver)
        self._bts_start_up_view = BtsStartUpViewPage(driver)
        self._cells = CellsPage(driver)
        self._site_view = SiteViewPage(driver)
        self._detailed_site_view = DetailedSiteViewPage(driver)
        self._carrier_aggregation = CarrierAggregationPage(driver)
        self._data_streams_by_cell = DataStreamsByCellPage(driver)
        self._data_streams_by_carrier = DataStreamsByCarrierPage(driver)
        self._site_report = SiteReportPage(driver)


class CellsPage(v24r3.bts_status.CellsPage):

    _MENU_ROUTE_LIST = ['Status', 'Site Runtime View', 'Cells']

    def __init__(self, driver):
        super(CellsPage, self).__init__(driver)
        self._detail_panel = CellsPageDetailPanel(driver)


class CellsPageDetailPanel(v24r3.bts_status.CellsPageDetailPanel):
    _LOCK_OR_UNLOCK_BUTTON_XPATH = '//div[@dist-name="operationDistName"]//ui-button[contains(@a-text, "lock Cell")]'
    _RESET_BUTTON_XPATH = '//div[@dist-name="operationDistName"]//ui-button[contains(@a-text, "Reset")]'
    _LOCK_STATUS = "Lock"
    _UNLOCK_STATUS = "Unlock"
    _RESET_STATUS = "Reset"
    _ADMINISTRATIVE_STATE_XPATH = '//td[contains(text(), "Blocking state:")]//following-sibling::td'

    def lock_cell(self, timeout):
        if self._UNLOCK_STATUS == self.get_text_by_xpath(self._LOCK_OR_UNLOCK_BUTTON_XPATH, timeout):
            raise UnexpectedElementState("Current status of cell is locked, no need to lock")

        self.click_enabled_element_after_visible((By.XPATH, self._LOCK_OR_UNLOCK_BUTTON_XPATH), timeout)
        self._change_cell_status_on_modal(self._LOCK_STATUS, timeout)
        self.wait_for_text_present_in_element((By.XPATH, self._ADMINISTRATIVE_STATE_XPATH), 'Blocked', timeout)

    def unlock_cell(self, timeout):
        if self._LOCK_STATUS == self.get_text_by_xpath(self._LOCK_OR_UNLOCK_BUTTON_XPATH, timeout):
            raise UnexpectedElementState("Current status of cell is unlock, no need to unlock")

        self.click_enabled_element_after_visible((By.XPATH, self._LOCK_OR_UNLOCK_BUTTON_XPATH), timeout)
        self._change_cell_status_on_modal(self._UNLOCK_STATUS, timeout)
        self.wait_for_text_present_in_element((By.XPATH, self._ADMINISTRATIVE_STATE_XPATH), 'Unblocked', timeout)


class BtsStartUpViewPage(bts_status.BtsStartUpViewPage):
    _MENU_ROUTE_LIST = ['Status', 'BTS Start-up View']


class SiteViewPage(v24r3.bts_status.SiteViewPage):
    """
    As a class will be called by BtsStatus, all operations on Site View will be implemented under this class.
    """
    _MENU_ROUTE_LIST = ['Status', 'Site Runtime View', 'Site View']


class DetailedSiteViewPage(v24r3.bts_status.DetailedSiteViewPage):
    """
    As a class will be called by BtsStatus, all operations on Detailed Site View will be implemented under this class.
    """
    _MENU_ROUTE_LIST = ['Status', 'Site Runtime View', 'Detailed Site View']

    def __init__(self, driver):
        super(DetailedSiteViewPage, self).__init__(driver)
        self._view_panel = DetailedSiteViewPageViewPanel(driver)
        self._detail_panel = DetailedSiteViewPageDetailPanel(driver)

    def get_site_cell_channel_info(self, cell_id):
        channel_elements = self._view_panel.collect_cell_channels(cell_id)
        channel_infos = []
        for channel_element in channel_elements:
            self._view_panel.show_channel_info_details(channel_element)
            channnel_info = self._detail_panel.collect_channel_details_info()
            channel_infos.append(channnel_info)
        return channel_infos


class DetailedSiteViewPageViewPanel(v24r3.bts_status.DetailedSiteViewPageViewPanel):

    _SITE_CELL_ELEMENTS_XPATH = '//div[@class="cell-row"]//span[contains(text(), "{cell_id}")]'
    _CHANNEL_ELEMENTS_XPATH = '//div[@class="cell-row"]//span[contains(text(), "{cell_id}")]/../../..//div[contains(@class, "site-cell-channel-container")]'

    def collect_cell_channels(self, cell_id):
        cell_element = self._driver.find_element_by_xpath(self._SITE_CELL_ELEMENTS_XPATH.format(cell_id=cell_id))
        self._driver.execute_script("arguments[0].scrollIntoView();", cell_element)
        return self._driver.find_elements(By.XPATH, self._CHANNEL_ELEMENTS_XPATH.format(cell_id=cell_id))

    def show_channel_info_details(self, channel_element):
        channel_element.click()


class DetailedSiteViewPageDetailPanel(v24r3.bts_status.DetailedSiteViewPageDetailPanel):

    _CELL_CHANNEL_OBJECT_NAME_XPATH = '//div[@class="element-name"]//span[contains(@class, "object-name-long")]'

    _PARAMETERS_TABLE_XPATH = '//table[contains(@class, "parameters-table")]'
    _PARAMETERS_TABLE_HEAD_XPATH = '(//table[contains(@class, "parameters-table")])[{table_id}]/thead/tr/th'
    _PARAMETERS_TABLE_ROW_XPATH = '(//table[contains(@class, "parameters-table")])[{table_id}]/tbody/tr'

    _VALUE_ROW_FEILD_XPATH = '/div'
    _STATE_ROW_FEILD_XPATH = '/div/div'
    _ELLIPSIS_ROW_FEILD_XPATH = "[@rowspan and @rowspan != '1']"

    def collect_channel_details_info(self):
        object_name = self._extract_channel_info_object_name()
        table_num = self._get_table_number()

        collected_info = {}
        tables_info = []
        for table_id in range(1, table_num + 1):
            titles = self._extract_table_titles(self._PARAMETERS_TABLE_HEAD_XPATH.format(table_id=table_id))
            row_num = self._get_table_row_number(self._PARAMETERS_TABLE_ROW_XPATH.format(table_id=table_id))

            rows_info = []
            ellipsis_crop_fields = None
            for row_id in range(1, row_num + 1):
                row_info = {}

                row_xpath = self._PARAMETERS_TABLE_ROW_XPATH.format(table_id=table_id) + '[{}]'.format(row_id)
                row_info, found_ellipsis_fields = self._extract_row_info(row_xpath, titles, ellipsis_crop_fields)
                if found_ellipsis_fields:
                    ellipsis_crop_fields = found_ellipsis_fields

                rows_info.append(row_info)

            tables_info.append(rows_info)

        collected_info[object_name] = tables_info

        return collected_info

    def _extract_table_titles(self, table_xpath):
        head_fields = self._driver.find_elements_by_xpath(table_xpath)
        return [field.text for field in head_fields]

    def _get_table_row_number(self, row_xpath):
        rows = self._driver.find_elements_by_xpath(row_xpath)
        return len(rows)

    def _extract_channel_info_object_name(self):
        elements = self._driver.find_elements_by_xpath(self._CELL_CHANNEL_OBJECT_NAME_XPATH)
        return elements[0].text if elements else "NA"

    def _get_table_number(self):
        tables = self._driver.find_elements_by_xpath(self._PARAMETERS_TABLE_XPATH)
        return len(tables)

    def _extract_row_info(self, row_xpath, titles, ellipsis_crop_fields):
        base_field_xpath = row_xpath + "/td"
        fields = self._driver.find_elements_by_xpath(base_field_xpath)
        field_num = len(fields)

        field_values = []
        found_ellipsis_fields = []
        for field_id in range(1, field_num + 1):
            field_xpath = base_field_xpath + '[{}]'.format(field_id)
            field_value, is_ellipsis = self._extract_field(field_xpath)
            if is_ellipsis:
                found_ellipsis_fields.append((field_id - 1, field_value))
            field_values.append(field_value)

        if len(field_values) == len(titles):
            return dict(zip(titles, field_values)), found_ellipsis_fields

        if ellipsis_crop_fields:
            for field_index, field_value in ellipsis_crop_fields:
                field_values.insert(field_index, field_value)
            return dict(zip(titles, field_values)), found_ellipsis_fields

    def _extract_field(self, field_xpath):
        is_ellipsis = False
        xpath = field_xpath + self._ELLIPSIS_ROW_FEILD_XPATH
        elems = self._driver.find_elements_by_xpath(xpath)
        if elems:
            is_ellipsis = True

        xpath = field_xpath + self._STATE_ROW_FEILD_XPATH
        elems = self._driver.find_elements_by_xpath(xpath)
        if elems:
            return elems[0].text or elems[0].get_attribute("ui-tooltip"), is_ellipsis

        xpath = field_xpath + self._VALUE_ROW_FEILD_XPATH
        elems = self._driver.find_elements_by_xpath(xpath)
        return elems[0].text, is_ellipsis


